  mail:`<svg width="28" height="28" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 6h16a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2Zm0 2v.2l8 5 8-5V8l-8 5-8-5Z" fill="currentColor"/></svg>`,
  camera:`<svg width="28" height="28" viewBox="0 0 24 24" aria-hidden="true"><path d="M8 5.5 9.4 4h5.2L16 5.5h3A2 2 0 0 1 21 7.5v9A2.5 2.5 0 0 1 18.5 19h-13A2.5 2.5 0 0 1 3 16.5v-9A2 2 0 0 1 5 5.5h3Zm4 3A4.2 4.2 0 1 0 16.2 12 4.2 4.2 0 0 0 12 8.5Zm0 1.8A2.4 2.4 0 1 1 9.6 12a2.4 2.4 0 0 1 2.4-1.7Z" fill="currentColor"/></svg>`,
